        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b11eec22e6fc235248b1af",
      "RuleLevel": "info",
      "RuleRegList": [
        {
          "RegDesc": "...发送富媒体消息 步骤一 > 上传文件至cos {本地文件路径：{{filepath}}、文件类型：{{filetype}}}[taskid：{{taskid}}]",
          "Reg": "\\|upload to cos\\|id:(?<taskid>\\d+)\\|file path:(?<filepath>[^ ]+) and type:(?<filetype>\\w+)"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b11f4022e6fc235248b1d0",
      "RuleLevel": "info",
      "RuleRegList": [
        {
          "RegDesc": "...发送富媒体消息 步骤二 > 请求cos签名 {文件md5值+后缀：{{file}}}[taskid：{{id}}]",
          "Reg": ".*RequestCosSignature.*\\|id:(?<id>\\d+)\\|file:(?<file>[^|]+)\\|save_region:.*"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b11f9a22e6fc235248b1e7",
      "RuleLevel": "info",
      "RuleRegList": [
        {
