          "Reg": "HandleCosSignatureResponse.*\\|id:(?<id>\\d+)\\|file:(?<file>[^|]+)\\|signature:file_id:\\d+,\\s*already_exist:(?<alreadyExist>\\d+),\\s*recommend_ip:(?<recommendIp>[^,]+),"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b11ffb22e6fc235248b202",
      "RuleLevel": "info",
      "RuleRegList": [
        {
          "RegDesc": "...发送富媒体消息 步骤三 > 启动本地文件上传 {id：{{id}}、上传url：{{url}}}",
          "Reg": ".*UploadLocalFile.*\\|step3\\|.*\\|id:(?<id>\\d+)\\|url:(?<url>[^\\s]+)"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b1203a22e6fc235248b223",
      "RuleLevel": "info",
      "RuleRegList": [
        {
          "RegDesc": "...发送富媒体消息 > 上传文件中 {id：{{id}}、上传进度：{{progress}}}",
