    {
      "RuleDesc": "",
      "Id": "68b120760f69c10259be7631",
      "RuleLevel": "info",
      "RuleRegList": [
        {
          "RegDesc": "发送富媒体消息 步骤三 < 上传文件完成 【id：{{id}}、cos请求Id：{{cosRequestId}}】",
          "Reg": ".*HandleUploadCompleted.*\\|id:(?<id>\\d+)\\|http status code:(?<httpStatusCode>\\d+)\\|cos_request_id:(?<cosRequestId>[^|]+).*"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b120ba22e6fc235248b24b",
      "RuleLevel": "info",
      "RuleRegList": [
        {
          "RegDesc": "...发送富媒体消息 步骤四 > 请求获取图片信息 {id：{{id}}、url：{{url}}}",
          "Reg": ".*RequestImageInfo.*\\|id:(?<id>\\d+)\\|url:(?<url>[^\\s]+).*"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b1210722e6fc235248b25f",
      "RuleLevel": "info",
      "RuleRegList": [
        {
          "RegDesc": "发送富媒体消息 步骤四 < 返回图片信息 【id：{{id}}、文件md5值+后缀：{{file}}、文件cos是否已存在：{{alreadyExist}}、推荐上传使用的ip：{{recommendIp}}】",
          "Reg": ".*HandleImageInfoResponse.*\\|id:(?<id>\\d+)\\|file:(?<file>[^|]+)\\|signature:file_id:\\d+, already_exist:(?<alreadyExist>\\d+), recommend_ip:(?<recommendIp>[^,]+).*"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b1214222e6fc235248b270",
      "RuleLevel": "info",
      "RuleRegList": [
        {
          "RegDesc": "...发送富媒体消息 结束 > 上传文件成功 【id：{{id}}】",
          "Reg": "NotifyUploadResult.*\\|upload to cos\\|id:(?<id>\\d+) success"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b121890f69c10259be76a0",
      "RuleLevel": "error",
      "RuleRegList": [
        {
          "RegDesc": "...发送富媒体消息 结束< $13 失败 【id：{{id}}、错误码：{{code}}、错误原因：{{errorMessage}}】",
          "Reg": "NotifyUploadResult.*id:(?<id>\\d+).*error code:(?<code>\\d+).*error message:(?<errorMessage>[^\\|]+)"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b121d222e6fc235248b299",
      "RuleLevel": "error",
      "RuleRegList": [
        {
          "RegDesc": "发送富媒体消息 上传文件终止 <【错误码：{{code}}、错误原因：{{errorMessage}}】",
          "Reg": "OnUploadCompleted.*error code:(?<code>\\d+)\\|error message:(?<errorMessage>.*)"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b1223122e6fc235248b2bd",
      "RuleLevel": "error",
      "RuleRegList": [
        {
          "RegDesc": "sdk内部发送消息前异常终止，原因【$10】",
          "Reg": "The message read receipt feature is available only to the Premium Edition\\. Please upgrade\\."
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b1227c22e6fc235248b2d9",
      "RuleLevel": "error",
      "RuleRegList": [
        {
          "RegDesc": "发送消息 < 失败【群组Id：{{groupId}}，错误原因：AVChatRoom直播群，需要客户端登录成功后，主动调用下 joinGroup 接口加群，才能发送消息】",
          "Reg": ".*OnGetGroupConversationInfo.*not allowed to send messages in an unjoined avchatroom.*group_id:(?<groupId>\\w+@\\d+)"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b124370f69c10259be7756",
      "RuleLevel": "info",
      "RuleRegList": [
        {
          "RegDesc": "······拉取历史消息返回的 item = 《{{set context = \"发送方Id：\" + senderUserId}}{{set timestamp = +clientTime}}{{set date = $imports.__date(timestamp * 1000)}}{{set dateStr = $imports.__dateFormat(date, \"yyyy-MM-dd\")}}{{set timeStr = $imports.__dateFormat(date, \"HH:mm:ss\")}}{{context}}、发送时间点：{{dateStr}} {{timeStr}}、sequence：{{sequence}}、random：{{random}}、消息状态：{{messageStatus}}》[TaskId:{{taskId}}]",
          "Reg": ".*ProcessMessageList\\s+\\|sender_user_id:(?<$10>\\d+)\\|client_time:(?<$11>\\d+)\\|server_time:(?<$12>\\d+)\\|sequence:(?<$13>\\d+)\\|random:(?<$14>\\d+)\\|message_status:(?<$15>\\w+)\\|task_id:(?<$16>\\d+)"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b1479522e6fc235248b3a0",
      "RuleLevel": "info",
      "RuleRegList": [
        {
          "RegDesc": "撤回消息 结束 < 返回结果【撤回失败，错误码：{{code}}、错误原因：】",
          "Reg": ".*HandleGroupRevokeResponse.*error code:(?<code>\\d+).*error message:"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b14a840f69c10259be7831",
      "RuleLevel": "error",
      "RuleRegList": [
        {
          "RegDesc": "撤回消息 结束 < 返回结果【撤回失败，错误码：{{code}}、错误原因：{{message}}】",
          "Reg": ".*HandleGroupRevokeResponse.*error code:(?<code>\\d+)\\|error message:(?<message>[^|]+).*"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b14b830f69c10259be785c",
      "RuleLevel": "info",
      "RuleRegList": [
        {
          "RegDesc": "撤回消息 请求 > 参数{{ set content = '' }}{{ if messageType === 'c2c' }}{{ set content = content + '单聊' }}{{ else }}{{ set content = content + '群聊' }}{{ /if }}{{ if isSender === 'true' }}{{ set content = content + '、消息发送方：是' }}{{ else }}{{ set content = content + '、消息发送方：否' }}{{ /if }}{{ set content = content + '、发送方ID：' + senderId }}{{ if messageType === 'c2c' }}{{ set content = content + '、接收方ID：' + receiverId }}{{ else }}{{ set content = content + '、群聊ID：' + groupId }}{{ /if }}{{ set content = content + '、消息ID：' + senderTinyId + '-' + random + '-' + clientTime }}{{ content }}",
          "Reg": "RevokeMessage.*\\|message_key:message_type:(?<messageType>\\w*)\\|is_message_sender:(?<isSender>true|false)\\|sender_user_id:(?<senderId>.*)\\|sender_tiny_id:(?<senderTinyId>\\d*)\\|receiver_user_id:(?<receiverId>.*)\\|receiver_tiny_id:(?<receiverTinyId>\\d*)\\|group_id:(?<groupId>.*)\\|client_time:(?<clientTime>\\d*)\\|server_time:(?<serverTime>\\d*)\\|sequence:(?<sequence>\\d*)\\|random:(?<random>\\d*)\\|reason:(?<reason>.*)"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b14c090f69c10259be7883",
      "RuleLevel": "info",
      "RuleRegList": [
        {
          "RegDesc": "撤回消息 结束 < 返回结果【撤回成功，{{if messageType === 'c2c'}}单聊{{else}}群聊{{/if}}{{if isSender === 'true'}}、消息发送方：是{{else}}、消息发送方：否{{/if}}、消息撤回方ID：{{revokerUserId}}、消息ID：{{senderTinyId}}-{{clientTime}}-{{random}}{{if revokerTinyId.length > 0}}、撤回原因：{{revokerTinyId}}{{/if}}】",
          "Reg": "HandleRevokedMessage.*\\|revoke_message_key_list:<message_type:(?<messageType>\\w*)\\|is_message_sender:(?<isSender>true|false)\\|sender_user_id:(?<senderUserId>.*)\\|sender_tiny_id:(?<senderTinyId>\\d*)\\|receiver_user_id:(?<receiverUserId>.*)\\|receiver_tiny_id:(?<receiverTinyId>\\d*)\\|group_id:(?<groupId>.*)\\|client_time:(?<clientTime>\\d*)\\|server_time:(?<serverTime>\\d*)\\|sequence:(?<sequence>\\d*)\\|random:(?<random>\\d*)>\\|revoker_tiny_id:(?<revokerTinyId>\\d*)\\|revoker_user_id:(?<revokerUserId>.*)\\|reason:(?<reason>.*)"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "68b160b10f69c10259be7912",
      "RuleLevel": "info",
      "RuleRegList": [
        {
          "RegDesc": "删除消息扩展 请求 > 参数{消息Id：{{senderTinyId}}-{{clientTime}}-{{random}}、key列表：{{keyList}}]}",
          "Reg": ".*DeleteMessageExtensions.*sender_tiny_id:(?<senderTinyId>\\d+).*server_time:(?<clientTime>\\d+).*random:(?<random>\\d+).*extension_key_list:(?<keyList>.*)"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "6912a518f6e677f92c5e5594",
      "RuleLevel": "error",
      "RuleRegList": [
        {
          "RegDesc": "重发消息 < 失败【消息信息：{{messageInfo}}】",
          "Reg": "SendMessage.*\\|resend failed message\\|(?<messageInfo>.*)"
        }
      ]
    },
    {
      "RuleDesc": "",
      "Id": "6912b95833013b7fd9cc9349",
      "RuleLevel": "error",
      "RuleRegList": [
        {
          "RegDesc": "发送消息 < 失败【错误码：{{code}}、错误原因：{{errorMsg}}】",
          "Reg": "InternalSendMessage.*\\|error code:(?<code>\\w*)\\|error message:(?<errorMsg>.*)"
        }
      ]
    }
  ]
},
{
